text(await tools.apply_patch("*** Begin Patch
*** Add File: enrichment/bible/work/s103/ehlikitap-images.sol.max.s103-20261009/sec7/verdicts.jsonl
+{"connection_id":"BC-3dc0803bfe4e68bc2fff","ref":"Augustine, Confessions 13.9.10","status":"unavailable","reason":"Augustine passage is absent from the frozen local snapshot; its weight metaphor cannot be verified here.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-391467a0995b28f2bc86","ref":"Didache 16:5","status":"unavailable","reason":"Didache passage is absent from the local snapshot, so the endurance wording is unverified.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-900bf8be1c5a7486ceea","ref":"Gospel of Thomas 90","status":"unavailable","reason":"Thomas saying is absent from the local snapshot; the proposed yoke wording cannot be checked.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-2faf39c4f8d44a8d0193","ref":"SBLGNT:1Cor.10.13","status":"rejected","reason":"Paul speaks of temptation within capacity, a moral test without the page's animal or travel scene; Matthew 11 supplies the load image more precisely.","paragraphs":[],"evidence":["SBLGNT:1Cor.10.13"],"annotations":[]}
+{"connection_id":"BC-098e8503ed4203efb9bc","ref":"SBLGNT:1Cor.10.13","status":"rejected","reason":"The verse limits testing, not a rider's imposed burden; Matthew 11 gives the closer physical load metaphor.","paragraphs":[],"evidence":["SBLGNT:1Cor.10.13"],"annotations":[]}
+{"connection_id":"BC-181fc2e34e3ef6f6b168","ref":"SBLGNT:1Cor.15.58","status":"rejected","reason":"The verse's labor not being vain lacks the load and journey frame; Ecclesiastes 1 and 5 make the gain and carrying question more exact.","paragraphs":[],"evidence":["SBLGNT:1Cor.15.58"],"annotations":[]}
+{"connection_id":"BC-f064eb097784b89c6ab4","ref":"SBLGNT:1Cor.15.58","status":"rejected","reason":"Steadfast work is present, but the proposed road and loss comparison adds less than Ecclesiastes' explicit gain and empty handed departure.","paragraphs":[],"evidence":["SBLGNT:1Cor.15.58"],"annotations":[]}
+{"connection_id":"BC-348179b36b24f9bfbb16","ref":"SBLGNT:1Cor.9.10","status":"rejected","reason":"Paul applies ox law to a worker's harvest share; the wage argument does not illuminate the camel's load or the road here.","paragraphs":[],"evidence":["SBLGNT:1Cor.9.10"],"annotations":[]}
+{"connection_id":"BC-7242392a2725c5376763","ref":"SBLGNT:1Cor.9.10","status":"rejected","reason":"This is Paul's human wage reading of the ox law, distinct from the page's capacity and humane pace; Exodus 23 supplies a closer duty.","paragraphs":[],"evidence":["SBLGNT:1Cor.9.10"],"annotations":[]}
+{"connection_id":"BC-dd9951e70baafa9aca5d","ref":"SBLGNT:1Cor.9.9","status":"rejected","reason":"The cited law concerns feeding a threshing ox, while the chosen Exodus law directly addresses a beast collapsed under its load.","paragraphs":[],"evidence":["SBLGNT:1Cor.9.9"],"annotations":[]}
+{"connection_id":"BC-0bf766b97416d757e0f7","ref":"SBLGNT:1Cor.9.9","status":"rejected","reason":"Paul asks about the ox law's human application; that interpretive turn concerns wages rather than the page's overloaded mount.","paragraphs":[],"evidence":["SBLGNT:1Cor.9.9"],"annotations":[]}
+{"connection_id":"BC-e55a8a1df7b17094b42b","ref":"SBLGNT:1John.2.10","status":"rejected","reason":"Stumbling is figurative offense within fraternal love, with no traveler or animal footing; the verbal overlap is too broad.","paragraphs":[],"evidence":["SBLGNT:1John.2.10"],"annotations":[]}
+{"connection_id":"BC-e364b7746db29782e649","ref":"SBLGNT:1John.3.18","status":"rejected","reason":"Love in deed and truth fits the surah generally, but it does not develop this paragraph's load, mount, or road image.","paragraphs":[],"evidence":["SBLGNT:1John.3.18"],"annotations":[]}
+{"connection_id":"BC-c9e9b7e3577467e1c4e8","ref":"SBLGNT:1John.5.3","status":"rejected","reason":"Commands are called not burdensome metaphorically; Matthew 11 gives a fuller yoke and rest image at this placement.","paragraphs":[],"evidence":["SBLGNT:1John.5.3"],"annotations":[]}
+{"connection_id":"BC-249b04be13610cf22398","ref":"SBLGNT:1Pet.2.20","status":"rejected","reason":"Enduring suffering for good conduct lacks the carried load or mountain way; it repeats the general patience motif without an image detail.","paragraphs":[],"evidence":["SBLGNT:1Pet.2.20"],"annotations":[]}
+{"connection_id":"BC-d6eea5e920ae59368ba4","ref":"SBLGNT:1Pet.2.24","status":"rejected","reason":"Christ bearing sins is a distinct atonement claim; the page cites losers bearing their own burdens, and Isaiah 46 better serves its carrier contrast.","paragraphs":[],"evidence":["SBLGNT:1Pet.2.24"],"annotations":[]}
+{"connection_id":"BC-570da1d13ee533801c53","ref":"SBLGNT:1Pet.2.24","status":"rejected","reason":"The verse shifts guilt to Christ rather than explaining the page's own burden image; its atonement setting would require a separate discussion.","paragraphs":[],"evidence":["SBLGNT:1Pet.2.24"],"annotations":[]}
