@@
+{"connection_id":"BC-fda6062d2c102b43022b","ref":"WLC:Isa.53.11","status":"rejected","reason":"The servant's soul toil and bearing others' iniquities belong to a particular suffering-servant argument; Ecclesiastes better tests general labor and gain.","paragraphs":[],"evidence":["WLC:Isa.53.11"],"annotations":[]}
